def _ann_outer(ann, types):
    "Find the outer annotation type if it matches `types`, including inside unions"
    if (origin := get_origin(ann)) in (Union, UnionType):
        return first(o for a in get_args(ann) if (o := _ann_outer(a, types)))
    origin = origin or ann
    return origin if isinstance(origin, type) and issubclass(origin, types) else None

def _allows_str(ann):
    "Whether annotation accepts strings directly"
    if ann is str or (isinstance(ann, type) and issubclass(ann, str)): return True
    if get_origin(ann) in (Union, UnionType): return any(_allows_str(a) for a in get_args(ann))
    return False

def coerce_inputs(func, inputs):
    "Coerce inputs based on function type annotations, repairing common LLM container mistakes"
    hints = get_type_hints(func) if hasattr(func, '__annotations__') else {}
    sig, res = inspect.signature(func), {}
    for k,v in inputs.items():
        ann = hints.get(k)
        if v is None and (p := sig.parameters.get(k)) and p.default is not empty: continue
        if ann in custom_types: res[k] = ann(v); continue
        cont, arr = _ann_outer(ann, (dict,list,tuple,set)), _ann_outer(ann, (list,tuple,set))
        if cont and isinstance(v, str) and not _allows_str(ann):
            try: v = ast.literal_eval(v)
            except Exception: pass
        if arr and v == {}: v = []
        elif arr and isinstance(v, str) and not _allows_str(ann): v = [v]
        if isinstance(v, dict) and callable(ann): res[k] = ann(**v)
        else: res[k] = v
    return res

