def resolve_nm(nm, ns):
    st,*rest = nm.split('.')
    return reduce(getattr, rest, ns[st])

# %% ../nbs/14_funccall.ipynb #6f6b5bfa
def get_schema_nm(nm:str, ns, dot2dash=False, **kwargs):
    "Get schema for symbol `nm` in namespace `ns`, preserving the full dotted name"
    name = nm.replace('.', '-') if dot2dash else nm
    return get_schema(resolve_nm(nm, ns), name=name, **kwargs)

# %% ../nbs/14_funccall.ipynb #f1e7f8b4
def _norm_nm(nm, repl=''): return re.sub(r'\W', repl, nm)

# %% ../nbs/14_funccall.ipynb #2fca0f67
def _py_nm(nm):
    nm = _norm_nm(nm, '_')
    if not nm: return '_'
    if nm and nm[0].isdigit(): nm = f'_{nm}'
    if keyword.iskeyword(nm): nm = f'{nm}_'
    return nm

# %% ../nbs/14_funccall.ipynb #1625929e
def _nm_map(nms):
    py2orig = {}
    for orig in nms:
        pynm = _py_nm(orig)
        prev = py2orig.get(pynm)
        if prev is not None and prev != orig:
            raise ValueError(f'Name collision after sanitizing: {prev!r} and {orig!r} -> {pynm!r}')
        py2orig[pynm] = orig
    return py2orig

# %% ../nbs/14_funccall.ipynb #47b49644
def call_func(fc_name, fc_inputs, ns, raise_on_err=True):
    "Call the function `fc_name` with the given `fc_inputs` using namespace `ns`."
    if not isinstance(ns, abc.Mapping): ns = mk_ns(ns)
    func = resolve_nm(fc_name, ns)
    inps = {_norm_nm(k):v for k,v in fc_inputs.items()}
    inps = coerce_inputs(func, inps)
    try: return func(**inps)
    except Exception as e:
        if raise_on_err: raise e from None
        else: return traceback.format_exc()

